const metaData = $('Fetch Meta Ads 7 Days').item.json;
const googleData = $('Fetch Google Ads 7 Days').item.json;
const budgetHistory = $('Fetch Budget History').all().map(i => i.json);

const dailyBudget = parseFloat($env.DAILY_AD_BUDGET || 50);
const targetCPA = parseFloat($env.TARGET_CPA || 15);

// Process Meta campaigns - 7 day performance
const metaCampaigns = (metaData.data || []).map(c => {
  const conversions = (c.actions || []).find(a => a.action_type === 'offsite_conversion');
  const spend = parseFloat(c.spend || 0);
  const convCount = parseInt(conversions?.value || 0);
  return {
    platform: 'meta',
    campaign_id: c.campaign_id,
    campaign_name: c.campaign_name,
    spend_7d: spend,
    avg_daily_spend: spend / 7,
    impressions: parseInt(c.impressions || 0),
    clicks: parseInt(c.clicks || 0),
    conversions: convCount,
    ctr: parseFloat(c.ctr || 0),
    cpc: parseFloat(c.cpc || 0),
    cpa: convCount > 0 ? spend / convCount : 999,
    roas_score: convCount > 0 ? (convCount * targetCPA) / spend : 0
  };
});

// Process Google campaigns
const googleCampaigns = (googleData.results || []).map(r => {
  const m = r.metrics || {};
  const spend = parseInt(m.costMicros || 0) / 1000000;
  const convCount = parseFloat(m.conversions || 0);
  return {
    platform: 'google',
    campaign_id: r.campaign?.id,
    campaign_name: r.campaign?.name,
    spend_7d: spend,
    avg_daily_spend: spend / 7,
    impressions: parseInt(m.impressions || 0),
    clicks: parseInt(m.clicks || 0),
    conversions: convCount,
    ctr: m.impressions > 0 ? (m.clicks / m.impressions * 100) : 0,
    cpc: m.clicks > 0 ? spend / parseInt(m.clicks) : 0,
    cpa: convCount > 0 ? spend / convCount : 999,
    roas_score: convCount > 0 ? (convCount * targetCPA) / spend : 0
  };
});

const allCampaigns = [...metaCampaigns, ...googleCampaigns];
const totalSpend7d = allCampaigns.reduce((s, c) => s + c.spend_7d, 0);
const totalConversions = allCampaigns.reduce((s, c) => s + c.conversions, 0);

// Classify campaigns by performance tier
const tiers = {
  star: allCampaigns.filter(c => c.cpa < targetCPA * 0.7 && c.conversions >= 2),
  good: allCampaigns.filter(c => c.cpa >= targetCPA * 0.7 && c.cpa <= targetCPA && c.conversions >= 1),
  underperform: allCampaigns.filter(c => c.cpa > targetCPA && c.cpa <= targetCPA * 2),
  waste: allCampaigns.filter(c => c.cpa > targetCPA * 2 || (c.spend_7d > dailyBudget && c.conversions === 0))
};

return {
  json: {
    daily_budget: dailyBudget,
    target_cpa: targetCPA,
    campaigns: allCampaigns,
    tiers: {
      star: tiers.star.map(c => c.campaign_id),
      good: tiers.good.map(c => c.campaign_id),
      underperform: tiers.underperform.map(c => c.campaign_id),
      waste: tiers.waste.map(c => c.campaign_id)
    },
    summary: {
      total_campaigns: allCampaigns.length,
      total_spend_7d: totalSpend7d,
      avg_daily_spend: totalSpend7d / 7,
      total_conversions: totalConversions,
      avg_cpa: totalConversions > 0 ? totalSpend7d / totalConversions : null,
      budget_utilization: (totalSpend7d / 7) / dailyBudget
    },
    budget_history: budgetHistory.slice(0, 7)
  }
};

