const aiResponse = $input.item.json.message.content;
let budgetPlan;
try { budgetPlan = JSON.parse(aiResponse); } catch (e) { budgetPlan = { error: 'Parse failed', raw: aiResponse }; }

const perfData = $('Analyze 7-Day Performance').item.json;

// Build API calls for budget updates
const metaUpdates = (budgetPlan.budget_plan || []).filter(c => c.platform === 'meta' && c.change_pct !== 0);
const googleUpdates = (budgetPlan.budget_plan || []).filter(c => c.platform === 'google' && c.change_pct !== 0);

return {
  json: {
    report_type: 'budget_reallocation',
    generated_at: new Date().toISOString(),
    agent_id: 'media-buyer',
    workflow_id: 'WF-ADS-BUDGET',
    daily_budget: perfData.daily_budget,
    budget_plan: budgetPlan,
    meta_updates: metaUpdates,
    google_updates: googleUpdates,
    total_changes: metaUpdates.length + googleUpdates.length,
    performance_summary: perfData.summary
  }
};
